// Every command is answered by the Swift side (ios/Sources/LacticPhonePlugin.swift); this list
// gives each one its permission (permissions/autogenerated).
const COMMANDS: &[&str] = &[
    "status",
    "authorize_health",
    "read_health",
    "take_pending",
    "ack_pending",
    "save_workout",
    "pair",
    "unpair",
    "send",
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();
}
